    public String serviceLink(){return DevGramIntegrationActions.link(row,data);}
    private void openService(){if(!preview&&allowed()){String link=serviceLink();if(!link.isEmpty())org.telegram.messenger.browser.Browser.openUrl(getContext(),link);}}
    public boolean performPrimaryAction(){
        if(preview||!allowed())return true;
        org.telegram.ui.ActionBar.BaseFragment host=org.telegram.ui.LaunchActivity.getSafeLastFragment();
        if(host==null||host.getCurrentAccount()!=account)return true;
        if(service==2){DevGramSteamGamesSheet.show(host,owner,row,serviceLink());return true;}
        if((service==3||service==4||service==5)&&selection()[0]==0&&playing(data)!=null){DevGramListenTogetherSheet.show(host,owner,row);return true;}
        int action=row.optInt("action",1);
        if(action==1||action==4){openService();return true;}
        return false;
    }
    private void syncEvents(){boolean wanted=attached&&!preview&&allowed()&&isShown()&&hasWindowFocus()&&getGlobalVisibleRect(visibleRect)&&(service==0||service==3||service==4||service==5||service==8);if(wanted&&events==null)events=new DevGramMusicEvents(account,owner,row.optString("id"),()->{if(!attached||!allowed())return;generation++;DevGramProfileIntegrations.invalidateRow(owner,row.optString("id"));load();DevGramListenTogether.refresh();});else if(!wanted&&events!=null){events.close();events=null;}}
    @Override protected void onVisibilityChanged(android.view.View changed,int visibility){super.onVisibilityChanged(changed,visibility);if(row!=null)syncEvents();}
    @Override protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);if(row!=null)syncEvents();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(row!=null)syncEvents();}
    private String value(int part){if(data==null)return "—";String key="";switch(service){case 0:key=new String[]{"track","scrobbles","artist","album"}[part];break;case 1:key=new String[]{"repositories","stars","followers","following","joined"}[part];break;case 2:key=new String[]{"state","joined","recentHours","name","level","games","hours","recentGame"}[part];break;case 3:key=new String[]{"track","lastLike","likes","playlists"}[part];break;case 4:key=new String[]{"track","lastTrack","topArtist","followers"}[part];break;case 5:key=new String[]{"lastTrack","followers","tracks","likes"}[part];break;case 7:key=new String[]{"name","state","activity","customStatus","track","joined","badges","guilds","clan"}[part];break;default:if(part==0)key="state";break;}if(service==2&&part==0&&!data.has("state")&&data.has("stateCode")){String[] states={"Не в сети","В сети","Занят","Отошёл","Нет на месте","В поиске обмена","В поиске игры"};return t(states[Math.max(0,Math.min(6,data.optInt("stateCode")))]);}
        if(service==7&&part==1&&data.has("presence")){switch(data.optString("presence")){case "online":return t("В сети");case "idle":return t("Нет на месте");case "dnd":return t("Не беспокоить");case "offline":return t("Не в сети");}}
        if(service==7&&part==6&&data.optJSONArray("badges")!=null){org.json.JSONArray badges=data.optJSONArray("badges");java.util.ArrayList<String> labels=new java.util.ArrayList<>();for(int i=0;i<badges.length();i++){String label;switch(badges.optString(i)){case "staff":label="Сотрудник Discord";break;case "partner":label="Партнёр Discord";break;case "hypesquad":label="HypeSquad";break;case "bug_hunter":label="Охотник за ошибками";break;case "bug_hunter_gold":label="Золотой охотник за ошибками";break;case "bravery":label="HypeSquad Bravery";break;case "brilliance":label="HypeSquad Brilliance";break;case "balance":label="HypeSquad Balance";break;case "early_supporter":label="Ранний поддержавший Discord";break;case "verified_bot":label="Проверенный бот";break;case "early_developer":label="Ранний разработчик Discord";break;case "moderator":label="Модератор Discord";break;case "active_developer":label="Активный разработчик Discord";break;default:continue;}labels.add(t(label));}return labels.isEmpty()?t("Нет"):android.text.TextUtils.join(" · ",labels);}
        Object value=data.opt(key);return value==null||value==JSONObject.NULL||String.valueOf(value).isEmpty()?"—":String.valueOf(value);}
    private void load(){if(preview||!allowed())return;int request=++generation;DevGramProfileIntegrations.loadRow(account,owner,row,cards->{if(!attached||request!=generation||!allowed())return;JSONObject next=null;for(int i=0;i<cards.length();i++){JSONObject card=cards.optJSONObject(i);if(card!=null&&DevGramProfileRowSpec.PROVIDERS[service].equals(card.optString("provider"))&&row.optString("url").equals(card.optString("handle"))){next=card;break;}}if(next==null)try{next=new JSONObject().put("status","unavailable");}catch(Exception ignored){}if(data==null||!data.toString().equals(next.toString())){applyData(next);}});}
    @Override protected void onLayout(boolean changed,int left,int top,int right,int bottom){super.onLayout(changed,left,top,right,bottom);if(row!=null)syncEvents();}
    @Override protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;getViewTreeObserver().addOnScrollChangedListener(scroll);DevGramProfilePolicy.listen(policy);policy.run();if(!preview){postDelayed(tick,15000);}}
    @Override protected void onDetachedFromWindow(){attached=false;syncEvents();if(getViewTreeObserver().isAlive())getViewTreeObserver().removeOnScrollChangedListener(scroll);generation++;DevGramProfilePolicy.unlisten(policy);removeCallbacks(tick);super.onDetachedFromWindow();}
